-- ---------------------------------------------------------------- CONFERENCIA
-- Rodar depois do COMMIT. Todos os md5 tem que bater com os comentarios acima.
SELECT ID, MD5(post_content) AS md5_atual, LENGTH(post_content) AS bytes
  FROM `wp_posts` WHERE ID IN (547432,547414,547416,547422,547428,547430);
SELECT option_name, MD5(option_value) AS md5_atual, LENGTH(option_value) AS bytes
  FROM `wp_options` WHERE option_name IN ('td_011','wpseo_titles','td_011_settings');
-- postmeta: contagem por objeto e conferencia de que nao ha chave duplicada
SELECT post_id, COUNT(*) AS linhas FROM `wp_postmeta`
 WHERE post_id IN (547432,547414,547416,547422,547428,547430) GROUP BY post_id;
SELECT COUNT(*) AS chaves_duplicadas FROM (SELECT post_id, meta_key FROM `wp_postmeta`
 WHERE post_id IN (547432,547414,547416,547422,547428,547430)
 GROUP BY post_id, meta_key HAVING COUNT(*) > 1) x;   -- tem que dar 0
